/* ---------- Arena Tests ---------- */

static void test_arena_basic(void) {
  printf("Running test_arena_basic...\n");

  arena_t* a = arena_create(64);
  assert(a);

  int* x = arena_alloc(a, sizeof *x, alignof(int));
  double* y = arena_alloc(a, sizeof *y, alignof(double));
  char* s = arena_alloc(a, 10, alignof(char));

  assert(x && y && s);
  *x = 42;
  *y = 3.14159;
  strcpy(s, "test");

  assert(*x == 42);
  assert(*y > 3.14 && *y < 3.15);
  assert(strcmp(s, "test") == 0);

  arena_destroy(a);
  printf("[PASS] test_arena_basic\n\n");
}

static void test_arena_growth(void) {
  printf("Running test_arena_growth...\n");

  arena_t* a = arena_create(32);
  assert(a);

  for (int i = 0; i < 100; i++) {
    int* p = arena_alloc(a, sizeof *p, alignof(int));
    assert(p);
    *p = i;
  }

  arena_destroy(a);
  printf("[PASS] test_arena_growth\n\n");
}

/* ---------- Runtime Tests ---------- */

static void test_runtime_init_shutdown(void) {
  printf("Running test_runtime_init_shutdown...\n");

  andy_runtime_init();
  arena_t* a = andy_get_global_arena();
  assert(a);

  int* x = arena_alloc(a, sizeof *x, alignof(int));
  assert(x);
  *x = 123;
  assert(*x == 123);

  andy_runtime_shutdown();
  printf("[PASS] test_runtime_init_shutdown\n\n");
}

/* ---------- Types Tests ---------- */

static void test_andy_string(void) {
  printf("Running test_andy_string...\n");

  arena_t* a = arena_create(128);
  assert(a);

  andy_string* s = arena_alloc(a, sizeof *s, alignof(andy_string));
  s->length = 5;
  s->data = arena_alloc(a, 6, alignof(char));
  memcpy(s->data, "hello", 6);

  assert(s->length == 5);
  assert(strcmp(s->data, "hello") == 0);

  arena_destroy(a);
  printf("[PASS] test_andy_string\n\n");
}

