/* ---------- I/O Tests ---------- */

static void test_andy_read_string(void) {
  printf("Running test_andy_read_string...\n");
  printf("Please enter the string: hello\n");

  arena_t* a = arena_create(128);
  assert(a);

  andy_string* s = andy_read_string(a);
  assert(s);
  assert(strcmp(s->data, "hello") == 0);
  assert(s->length == 5);

  arena_destroy(a);
  printf("[PASS] test_andy_read_string\n\n");
}

